pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seedAmount, uint256 withdrawAmount) public {
        // admissible domain: fund with seedAmount, then withdraw a strictly partial amount
        seedAmount = bound(seedAmount, 2 ether, 100 ether);
        withdrawAmount = bound(withdrawAmount, 1 wei, seedAmount - 1); // partial withdraw

        address actor = address(0xABCD);
        vm.deal(actor, withdrawAmount);
        vm.prank(actor);
        c.fallback{value: seedAmount}(); // fund c via the payable fallback

        uint256 balanceBefore = address(c).balance;
        require(balanceBefore == seedAmount);
        require(withdrawAmount < balanceBefore);

        vm.prank(c.owner()); // owner-only entry point
        c.withdraw(withdrawAmount);

        // General rule: after withdraw(v), c's balance is exactly balanceBefore - v.
        // Correct C: transfers v. Buggy M: transfers address(c).balance (entire balance),
        // so the remaining balance is 0 != balanceBefore - v (which is >= 1 wei).
        assertTrue(address(c).balance == balanceBefore - withdrawAmount);
    }
}

