    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(msg.sender != c.owner());
        require(address(this).balance >= amount);
        c.fallback{value: amount};
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint value) public payable {
        require(msg.sender != c.owner());
        require(c.owner() != address(this));
        bool reverted;
        try c.withdraw(value) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public {
        bool isOwner = (msg.sender == c.owner());
        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        assert(reverted == !isOwner);
    }
    receive() external payable {}
}
